function Clear-PackageView($Window){$state=$Window.Tag;$Window.FindName('Picture').Source=$null;$Window.FindName('Details').Text='';$Window.FindName('Placeholder').Text='Select a stored item after unlocking.';if($state.Inspection){$state.Inspection.Dispose();$state.Inspection=$null}}
function Update-PackageControls($Window){$state=$Window.Tag;$session=$state.Session;$ready=$session.Ready -and -not $state.Closing;$idle=$ready -and -not $session.Busy;$unlocked=$ready -and $session.Unlocked
    $Window.FindName('Password').IsEnabled=$idle -and -not $unlocked;$Window.FindName('Unlock').IsEnabled=$idle -and -not $unlocked;$Window.FindName('Lock').IsEnabled=$unlocked;$Window.FindName('Cancel').IsEnabled=$session.Busy -and -not $state.Closing
    $Window.FindName('Items').IsEnabled=$unlocked -and ($idle -or $session.Status.Kind -eq 'Inspect');$Window.FindName('Export').IsEnabled=$idle -and $unlocked -and $state.Inspection -and $state.Inspection.Verified;$Window.FindName('Close').IsEnabled=-not $state.Closing
}
function Apply-PackageResult($Window,[MediaReviewer.PackageResult]$Reply){$state=$Window.Tag;if(-not $Reply.Durable -and ($state.Closing -or $Reply.Generation -ne $state.Generation)){$Reply.Dispose();return $false}
    if(-not $Reply.Success){$Window.FindName('Status').Text=$Reply.Error;Update-PackageControls $Window;return $true}
    if($Reply.Kind -eq 'Unlock'){$Window.FindName('Items').ItemsSource=$Reply.Items}
    if($Reply.Kind -eq 'Inspect'){Clear-PackageView $Window;$state.Inspection=$Reply.Inspection;$Window.FindName('Details').Text=$Reply.Details;$Window.FindName('Picture').Source=$Reply.Inspection.PreviewImage;$Window.FindName('Placeholder').Text=if($Reply.Inspection.PreviewImage){''}elseif($Reply.Inspection.PreviewError){$Reply.Inspection.PreviewError}else{'Saved preview unavailable. The retained original is verified and can be exported.'}}
    $Window.FindName('Status').Text=$Reply.Value;Update-PackageControls $Window;return $true
}
function Invoke-PackageTick($Window){$state=$Window.Tag;if($state.Session.Closed){$state.Timer.Stop();if($state.Session.OutputWarning -and -not $state.CloseWarningShown){$state.CloseWarningShown=$true;[void][Windows.MessageBox]::Show($Window,$state.Session.OutputWarning,'Check incomplete original output',[Windows.MessageBoxButton]::OK,[Windows.MessageBoxImage]::Warning)};if($Window.IsVisible){$state.AllowClose=$true;$Window.Close()};return}
    $reply=$state.Session.TakeResult();if($reply){[void](Apply-PackageResult $Window $reply)}elseif($state.Session.Busy -or $state.Session.Status.State -in @('failed','cancelled','closing')){$Window.FindName('Status').Text=$state.Session.Status.Stage};Update-PackageControls $Window
}
function Start-PackageOriginalExport($Window,[string]$Destination){$state=$Window.Tag;try{$state.Generation=$state.Session.RequestExport($Window.FindName('Items').SelectedIndex,$Destination);$Window.FindName('Status').Text='Export queued. The verified original will be plaintext at the chosen destination.'}catch{$Window.FindName('Status').Text=$_.Exception.Message};Update-PackageControls $Window}
function New-PackageWindow([string]$Path,$Owner=$null){
    if($script:packageWindow -and -not $script:packageWindow.Tag.Session.Closed){throw 'Close the current protected package before opening another.'}
    $markup=@'
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml" Title="Protected Evidence package - read only" Width="940" Height="700" MinWidth="700" MinHeight="540" FontFamily="Segoe UI" FontSize="14" WindowStartupLocation="CenterScreen">
 <Grid Margin="16"><Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="*"/><RowDefinition Height="76"/><RowDefinition Height="Auto"/></Grid.RowDefinitions>
  <TextBlock Text="This package opens read only. Unlock to view saved details and thumbnails. Export original writes a verified full-resolution plaintext file only to the destination you choose." TextWrapping="Wrap" Margin="0,0,0,12"/>
  <WrapPanel Grid.Row="1" Margin="0,0,0,12"><TextBlock Text="Originals password" VerticalAlignment="Center" Margin="0,0,8,0"/><PasswordBox x:Name="Password" Width="230" MinHeight="32" Padding="5"/><Button x:Name="Unlock" Content="Unlock" Padding="14,5" Margin="8,0,0,0" IsDefault="True"/><Button x:Name="Lock" Content="Lock" Padding="14,5" Margin="8,0,0,0"/><Button x:Name="Cancel" Content="Cancel task" Padding="14,5" Margin="8,0,0,0"/></WrapPanel>
  <Grid Grid.Row="2"><Grid.ColumnDefinitions><ColumnDefinition Width="235"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions><ListBox x:Name="Items" HorizontalContentAlignment="Stretch" ScrollViewer.HorizontalScrollBarVisibility="Disabled"/><Grid Grid.Column="1" Margin="12,0,0,0"><Grid.RowDefinitions><RowDefinition Height="*"/><RowDefinition Height="190"/></Grid.RowDefinitions><Border Background="#EAF0F5"><Grid><Image x:Name="Picture" Stretch="Uniform"/><TextBlock x:Name="Placeholder" Text="Details remain protected until authentication completes." TextWrapping="Wrap" HorizontalAlignment="Center" VerticalAlignment="Center" Margin="18"/></Grid></Border><TextBox Grid.Row="1" x:Name="Details" IsReadOnly="True" TextWrapping="Wrap" VerticalScrollBarVisibility="Auto" Margin="0,10,0,0"/></Grid></Grid>
  <TextBlock Grid.Row="3" x:Name="Status" Text="Opening protected package..." TextWrapping="Wrap" VerticalAlignment="Center"/>
  <StackPanel Grid.Row="4" Orientation="Horizontal" HorizontalAlignment="Center"><Button x:Name="Export" Content="Export original..." Padding="20,7" Margin="6"/><Button x:Name="Close" Content="Close" IsCancel="True" Padding="20,7" Margin="6"/></StackPanel>
 </Grid>
</Window>
'@
    $window=[Windows.Markup.XamlReader]::Parse($markup);if($Owner){$window.Owner=$Owner;$window.WindowStartupLocation='CenterOwner'};$session=[MediaReviewer.EvidencePackageSession]::Open($Path);$state=[pscustomobject]@{Session=$session;Generation=[long]0;Inspection=$null;Timer=$null;Closing=$false;AllowClose=$false;CloseWarningShown=$false};$window.Tag=$state;$script:packageWindow=$window
    $window.FindName('Unlock').Add_Click({param($sender,$event) $w=[Windows.Window]::GetWindow($sender);$s=$w.Tag;$bytes=$null;try{$bytes=Get-UiPasswordBytes $w.FindName('Password').SecurePassword;$w.FindName('Password').Clear();$s.Generation=$s.Session.RequestUnlock($bytes);$bytes=$null;$w.FindName('Status').Text='Authenticating package in the background...'}catch{$w.FindName('Status').Text=$_.Exception.Message}finally{if($bytes){[Array]::Clear($bytes,0,$bytes.Length)}};Update-PackageControls $w})
    $window.FindName('Items').Add_SelectionChanged({param($sender,$event) $w=[Windows.Window]::GetWindow($sender);if($sender.SelectedIndex -lt 0 -or -not $w.Tag.Session.Unlocked){return};Clear-PackageView $w;$w.FindName('Placeholder').Text='Loading and verifying stored original...';try{$w.Tag.Generation=$w.Tag.Session.RequestInspect($sender.SelectedIndex);$w.FindName('Status').Text='Authenticating the selected original...'}catch{$w.FindName('Status').Text=$_.Exception.Message};Update-PackageControls $w})
    $window.FindName('Lock').Add_Click({param($sender,$event) $w=[Windows.Window]::GetWindow($sender);Clear-PackageView $w;$w.FindName('Password').Clear();$w.FindName('Items').ItemsSource=$null;try{$w.Tag.Generation=$w.Tag.Session.RequestLock();$w.FindName('Status').Text='Locking package; protected views cleared.'}catch{$w.FindName('Status').Text=$_.Exception.Message};Update-PackageControls $w})
    $window.FindName('Cancel').Add_Click({param($sender,$event) $w=[Windows.Window]::GetWindow($sender);if(-not $w.Tag.Session.Ready){$w.Close()}else{$w.Tag.Session.Cancel();$w.Tag.Generation=$w.Tag.Session.Generation;$w.FindName('Status').Text='Cancelling; waiting for the owned operation.';Update-PackageControls $w}})
    $window.FindName('Export').Add_Click({param($sender,$event) $w=[Windows.Window]::GetWindow($sender);$picker=[Microsoft.Win32.SaveFileDialog]::new();$picker.Title='Export verified plaintext original to a new file';$picker.Filter='Original media|*.*';$picker.FileName='Verified-original.bin';$picker.OverwritePrompt=$false;if($picker.ShowDialog($w)){Start-PackageOriginalExport $w $picker.FileName}})
    $window.FindName('Close').Add_Click({param($sender,$event) [Windows.Window]::GetWindow($sender).Close()})
    $window.Add_Closing({param($sender,$event) $s=$sender.Tag;if(-not $s.AllowClose){$event.Cancel=$true;$s.Closing=$true;Clear-PackageView $sender;$sender.FindName('Password').Clear();$sender.FindName('Items').ItemsSource=$null;$s.Session.CloseAsync();Update-PackageControls $sender}})
    $window.Add_Closed({param($sender,$event) $sender.Tag.Timer.Stop();Clear-PackageView $sender;$sender.Tag.Session.CloseAsync();if($script:packageWindow -eq $sender){$script:packageWindow=$null}})
    $timer=[Windows.Threading.DispatcherTimer]::new();$timer.Interval=[TimeSpan]::FromMilliseconds(100);$timer.Tag=$window;$timer.Add_Tick({param($sender,$event) Invoke-PackageTick $sender.Tag});$state.Timer=$timer;$timer.Start();Update-PackageControls $window;return $window
}
function Show-UiPackage([string]$Path){try{if($script:packageWindow -and -not $script:packageWindow.Tag.Session.Closed){$script:packageWindow.Activate() | Out-Null;Set-UiMessage 'Close the current protected package before opening another.';return};$window=New-PackageWindow $Path $script:reviewUi.Window;$window.Show()}catch{Set-UiMessage $_.Exception.Message}}
function Start-PackageInterface([string]$Path){$window=New-PackageWindow $Path;[void]$window.ShowDialog()}
function Invoke-UiPackageExport {
    $u=$script:reviewUi;if(-not $u.Engine -or -not $u.Engine.Ready -or $u.MaintenancePending){return};$cards=@($u.Cards | Where-Object {$_.IsSelected -and -not $_.IsPending});if(-not $cards.Count -or $cards.Count -gt 200){Set-UiMessage 'Select one through 200 Non-compliant or Evidence items with stored originals.';return};if($u.Pending.Count -or ($u.DetailsWindow -and $u.DetailsWindow.Tag.Saving)){Set-UiMessage 'Wait for the pending review to commit before exporting.';return};if(-not $u.Engine.VaultUnlocked){Show-UiVaultDialog ([pscustomobject]@{Kind='Package'});return}
    $picker=[Microsoft.Win32.SaveFileDialog]::new();$picker.Title='Export selected encrypted stored originals';$picker.Filter='Protected Evidence package|*.mcrevidence';$picker.FileName='Media-Review-evidence.mcrevidence';$picker.OverwritePrompt=$false;if($picker.ShowDialog($u.Window)){try{$u.BackgroundOperationId=$u.Engine.RequestEvidencePackageExport([long[]]@($cards | ForEach-Object {$_.Record.GroupId}),$picker.FileName,[Guid]::NewGuid().ToString('N'));$u.MaintenancePending=$true;Set-UiMessage 'Protected package queued. Review changes pause; cached inspection remains available.'}catch{Set-UiMessage $_.Exception.Message};Update-UiControls}
}
function Add-UiPackageControls {
    $u=$script:reviewUi;$item=[Windows.Controls.MenuItem]::new();$item.Header='Export selected protected package...';$item.Add_Click({Invoke-UiPackageExport});$u.Controls.MaintenanceButton.ContextMenu.Items.Add($item) | Out-Null
}
